FUNCTION UNDER TEST:
Name: buffer_resize
Signature: int buffer_resize(buffer_t *self, size_t n)
Description: /**
 * @brief Resize a buffer to the nearest multiple of 1024 bytes.
 *
 * Adjusts the buffer's allocated memory to at least the specified size,
 * rounded up to the next multiple of 1024. Updates internal length and
 * ensures the buffer is null-terminated. If memory allocation fails,
 * the buffer is left unchanged.
 *
 * @param self Pointer to the buffer to resize. Must not be NULL.
 * @param n Desired minimum size in bytes.
 *
 * @return Returns 0 on success, or -1 if memory allocation fails.
 *
 * @note Error: On failure, the buffer's contents and allocation remain unchanged.
 */
Dependencies: None

FUNCTION IMPLEMENTATION:
```c
// C program for the function called buffer_resize
// Contains target function implementation and dependency signatures

#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <ctype.h>
#include <sys/types.h>
#include "buffer.h"

// Target function implementation
int
buffer_resize(buffer_t *self, size_t n) {
  n = nearest_multiple_of(1024, n);
  self->len = n;
  self->alloc = self->data = realloc(self->alloc, n + 1);
  if (!self->alloc) return -1;
  self->alloc[n] = '\0';
  return 0;
}

